class Solution:
    def getMaximumGold(self, grid: list[list[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        def dfs(r, c):
            if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == 0:
                return 0
            gold = grid[r][c]
            grid[r][c] = 0
            best = 0
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                best = max(best, dfs(r+dr, c+dc))
            grid[r][c] = gold
            return gold + best
        ans = 0
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] != 0:
                    ans = max(ans, dfs(r, c))
        return ans

